{
  "screens": [
    {
      "kind": "hookText",
      "text": "Mendel crossed pea plants with purple and white flowers, then counted thousands of seeds. White flowers returned in a regular pattern—how could a cross predict their share?",
      "image": null,
      "visual": null
    },
    {
      "kind": "explanation",
      "title": "Pairing the letters",
      "text": "Each parent passes one of its two letter versions. A **Punnett square** pairs one from each: Pp × pp gives two Pp and two pp. Pp is purple; only pp is white, so half the equally likely outcomes are white.",
      "exampleLineIdea": "Predicting the share of white flowers in a garden cross",
      "image": null,
      "visual": null,
      "explore": null
    },
    {
      "kind": "activity",
      "template": "combinationGrid",
      "content": "{\"template\":\"combinationGrid\",\"prompt\":\"Fill each square with the two letters that meet.\",\"fields\":{\"title\":\"Pp × pp\",\"rule\":\"alleles\",\"rows\":{\"label\":\"pp parent\",\"values\":[\"p\",\"p\"]},\"columns\":{\"label\":\"Pp parent\",\"values\":[\"P\",\"p\"]},\"traits\":{\"dominant\":\"purple flowers\",\"recessive\":\"white flowers\"}},\"check\":{\"kind\":\"choice\",\"output\":\"recessive\",\"question\":\"What share of these seeds should grow white flowers?\",\"options\":[{\"id\":\"half\",\"text\":\"1 in 2\",\"value\":0.5,\"isCorrect\":true,\"reason\":\"Two of the four squares are pp, and pp has white flowers.\"},{\"id\":\"quarter\",\"text\":\"1 in 4\",\"value\":0.25,\"isCorrect\":false,\"reason\":\"One in four comes from a Pp × Pp cross, not this Pp × pp cross.\"},{\"id\":\"threequarters\",\"text\":\"3 in 4\",\"value\":0.75,\"isCorrect\":false,\"reason\":\"Three squares are not white here. Only the two pp squares have white flowers.\"}]}}"
    },
    {
      "kind": "activity",
      "template": "randomSimulation",
      "content": "{\"template\":\"randomSimulation\",\"prompt\":\"Each seed has a 1-in-2 chance of white flowers. Guess how often batches of 100 have exactly 50 white flowers, then simulate many batches.\",\"fields\":{\"mode\":\"chance\",\"model\":{\"kind\":\"binomial\",\"trials\":100,\"probability\":0.5,\"hit\":{\"comparison\":\"exactly\",\"value\":50}},\"trialLabel\":\"100-seed batch\",\"hitLabel\":\"exactly 50 white flowers\",\"runs\":1000},\"check\":{\"kind\":\"choice\",\"question\":\"What share of batches has exactly 50 white flowers?\",\"options\":[{\"id\":\"eight\",\"text\":\"About 8%\",\"value\":0.08,\"isCorrect\":true,\"reason\":\"The exact chance is about 8%, so most batches land on a different count.\"},{\"id\":\"fifty\",\"text\":\"About 50%\",\"value\":0.5,\"isCorrect\":false,\"reason\":\"Half the seeds are expected to be white, but that does not mean half the batches have exactly 50.\"},{\"id\":\"twentyfive\",\"text\":\"About 25%\",\"value\":0.25,\"isCorrect\":false,\"reason\":\"The chance of exactly 50 is much lower than one in four across repeated batches.\"},{\"id\":\"one\",\"text\":\"About 1%\",\"value\":0.01,\"isCorrect\":false,\"reason\":\"Exactly 50 happens more often than one batch in 100; its chance is about 8%.\"}]},\"data\":{\"isExample\":true}}"
    },
    {
      "kind": "check",
      "context": "In Louisville, Keisha plants 100 seeds from a Pp × pp cross and gets 47 white flowers.",
      "question": "Does this mean the 1-in-2 prediction was wrong?",
      "options": [
        {
          "text": "No. One batch can land near 50 without matching it.",
          "isCorrect": true,
          "reason": "A 1-in-2 chance sets an expectation, not a fixed count for each batch. Forty-seven is close to 50.",
          "picture": null
        },
        {
          "text": "Yes. The prediction requires exactly 50 in every batch.",
          "isCorrect": false,
          "reason": "A 1-in-2 chance does not force an even split in every batch. Counts can vary around 50.",
          "picture": null
        }
      ],
      "image": null,
      "visual": null,
      "basis": null
    }
  ],
  "summary": {
    "ideas": [
      {
        "label": "Punnett square",
        "text": "A Pp × pp cross has two Pp outcomes and two pp outcomes, so half are white."
      },
      {
        "label": "Chance across batches",
        "text": "A 1-in-2 chance does not make every batch exactly half white; exactly 50 of 100 happens only about 8% of the time."
      }
    ],
    "shape": "hub"
  }
}

